<?php
require_once __DIR__.'/../includes/layout.php';$u=require_login('admin');
$q=db()->query("SELECT u.id,u.name,u.email,u.role,u.active,u.created_at,COALESCE(r.company_name,'') company_name FROM users u LEFT JOIN recruiter_profiles r ON r.user_id=u.id ORDER BY u.created_at DESC LIMIT 500");$rows=$q->fetchAll();page_header('Gestion des utilisateurs');
?><p>La suppression est définitive et supprime également les profils, offres, candidatures et notifications associés (selon les relations de la base).</p><div class="table-wrap"><table><thead><tr><th>Nom</th><th>E-mail</th><th>Rôle</th><th>Entreprise</th><th>Statut</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['name'])?></td><td><?=h($r['email'])?></td><td><?=h($r['role'])?></td><td><?=h($r['company_name'])?></td><td><?=$r['active']?'Actif':'Inactif'?></td><td><?php if($r['role']!=='admin'):?><form method="post" action="<?=h(url('admin/delete_user.php'))?>" onsubmit="return confirm('Supprimer définitivement ce compte et ses données ?')"><?=csrf_field()?><input type="hidden" name="id" value="<?=h((string)$r['id'])?>"><button class="danger">Supprimer</button></form><?php else:?>Compte administrateur<?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php page_footer();?>